where  b.axuserrole !=''All''  
union all
select b.axpermissionsid,b.axusername ,b.axuserrole ,b.formcap,coalesce(b.allowcreate,''Yes'') allowcreate,
 case b.viewctrl when ''0'' then ''All'' 
 when ''1'' then ''View these fields - ''||view_flds 
